epayAmount) external view returns (uint, uint); } contract InterestRateModel { bool public constant isInterestRateModel = true; function getBorrowRate(uint cash, uint borrows, uint reserves) external view returns (uint); function getSupplyRate(uint cash, uint borrows, uint reserves, uint reserveFactorMantissa) external view returns (uint); } interface EIP20NonStandardInterface { function totalSupply() external view returns (uint256); function balanceOf(address owner) external view returns (uint256 balance); function transfer(address dst, uint256 amount) external; function transferFrom(address src, address dst, uint256 amount) external; function approve(address spender, uint256 amount) external returns (bool success); function allowance(address owner, address spender) external view returns (uint256 remaining); event Transfer(address indexed from, address indexed to, uint256 amount); event Approval(address indexed owner, address indexed spender, uint256 amount); } contract CTokenStorage { bool internal _notEntered; string public name; string public symbol; uint8 public decimals; uint internal constant borrowRateMaxMantissa = 0.0005e16; uint internal constant reserveFactorMaxMantissa = 1e18; address payable public admin; address payable public pendingAdmin; ComptrollerInterface public comptroller; InterestRateModel public interestRateModel; uint internal initialExchangeRateMantissa; uint public reserveFactorMantissa; uint public accrualBlockNumber; uint public borrowIndex; uint public totalBorrows; uint public totalReserves; uint public totalSupply; mapping (address => uint) internal accountTokens; mapping (address => mapping (address => uint)) internal transferAllowances; struct BorrowSnapshot { uint principal; uint interestIndex; } mapping(address => BorrowSnapshot) internal accountBorrows; uint public constant protocolSeizeShareMantissa = 2.8e16; } contract CTokenInterface is CTokenStorage { bool public constant isCToken = true; event AccrueInterest(uint cashPrior, 